const taskKey=(workOrderNo:string,operationNo:string)=>`${clean(workOrderNo)}|${clean(operationNo)}`;
const isExternal=(part?:Part)=>part?.processMode==='external';
const PLAN_DAYS=6;
const workdaysUntil=(from:string,to:string)=>{if(!to||to<=from)return 0;let d=from,n=0,guard=0;while(d<to&&guard++<400){d=addDay(d);if(![0,6].includes(new Date(d+'T00:00:00').getDay()))n++}return n};
