const factoryFromRows=(rows:Record<string,unknown>[]):Factory|null=>{
 const fields=['责任单位','计划编制部门','生产车间(选择)','所属工厂','工厂'];let xian=0,xingping=0;
 for(const row of rows)for(const key of fields){const value=clean(row[key]);if(/西安/.test(value))xian++;if(/兴平/.test(value))xingping++}
 return xian&&!xingping?'xian':xingping&&!xian?'xingping':null
};

const mergeOfficialWorkers=(workers:Worker[]=[])=>{
 const matched=new Set<string>();
 const merged=officialLatheWorkers.map(official=>{
  const legacyNames=new Set([official.name,official.name.replace(/（[盘轴]）/g,''),official.name==='王超伟'?'王朝伟':'',official.name.startsWith('赵超阳')?'赵朝阳':''].filter(Boolean));
  const existing=workers.find(w=>w.id===official.id||legacyNames.has(w.name));
  if(existing)matched.add(existing.id);
  return existing?{...official,...existing,id:official.id,name:official.name,skills:[...existing.skills]}:{...official,skills:[...official.skills]};
 });
 return [...merged,...workers.filter(worker=>!matched.has(worker.id))];
};
const mergeConfirmedXianWorkers=(workers:Worker[]=[])=>{
 const matched=new Set<string>();
 const merged=confirmedXianLatheWorkers.map(confirmed=>{
  const existing=workers.find(worker=>worker.id===confirmed.id||worker.name===confirmed.name);
  if(existing)matched.add(existing.id);
  return existing?{...confirmed,...existing,id:confirmed.id,name:confirmed.name,skills:[...existing.skills]}:{...confirmed,skills:[...confirmed.skills]};
 });
 return [...merged,...workers.filter(worker=>!matched.has(worker.id))];
};

function schedule(state:AppState,useOvertime=false){
 const loads=new Map<string,number>(),out:Allocation[]=[],shortages:ScheduleShortage[]=[];
 const workOf=(o:Order)=>{const p=state.parts.find(x=>x.code===o.partCode);return Math.max(0,o.qty-o.done)*(p?.unit||0)};
 const orders=[...state.orders].filter(o=>o.status!=='已完成'&&o.qty>o.done&&!isExternal(state.parts.find(p=>p.code===o.partCode))).sort((a,b)=>a.priority-b.priority||a.due.localeCompare(b.due)||workOf(a)-workOf(b));
 for(const order of orders){
  const part=state.parts.find(p=>p.code===order.partCode);const requiredWork=Math.max(0,order.qty-order.done)*(part?.unit||0);if(!part||part.unit<=0){shortages.push({orderId:order.id,drawingNo:order.drawingNo||part?.drawingNo,orderNo:order.orderNo,partCode:order.partCode,name:order.name,due:order.due,requiredWork,scheduledWork:0,remainingWork:requiredWork,remainingQty:Math.max(0,order.qty-order.done),reason:'缺少单件工时值，无法排产'});continue}
  // Explicitly selected workers are a hard constraint. Category skills are
  // only a fallback for legacy parts that have no selected workers.
  const candidates=orderCandidates(order,part,state.workers); if(!candidates.length){shortages.push({orderId:order.id,drawingNo:order.drawingNo||part?.drawingNo,orderNo:order.orderNo,partCode:order.partCode,name:order.name,due:order.due,requiredWork,scheduledWork:0,remainingWork:requiredWork,remainingQty:Math.max(0,order.qty-order.done),reason:'没有已启用且具备该工件能力的人员'});continue}
  let best:{w:Worker,finish:string,plan:{date:string,amount:number}[],remaining:number,existingLoadRatio:number,finishRatio:number}|null=null;
  for(const w of candidates){let remain=requiredWork,d=workday(today()),guard=0;const cap=useOvertime?w.overtime:w.capacity,plan=[] as {date:string,amount:number}[],existingLoad=[...loads.entries()].filter(([key])=>key.startsWith(w.id+'|')).reduce((sum,[,value])=>sum+value,0);while(remain>.001&&guard++<PLAN_DAYS){const k=w.id+'|'+d,avail=Math.max(0,cap-(loads.get(k)||0));if(avail){const amount=Math.min(avail,remain);plan.push({date:d,amount});remain-=amount}if(remain>.001)d=workday(addDay(d))}const last=plan[plan.length-1],finishRatio=last?((loads.get(w.id+'|'+last.date)||0)+last.amount)/Math.max(1,cap):Number.POSITIVE_INFINITY,existingLoadRatio=existingLoad/Math.max(1,cap);if(!best||remain<best.remaining||(remain===best.remaining&&(d<best.finish||(d===best.finish&&(finishRatio<best.finishRatio||(finishRatio===best.finishRatio&&existingLoadRatio<best.existingLoadRatio))))))best={w,finish:d,plan,remaining:remain,existingLoadRatio,finishRatio}}
  if(!best)continue;const candidateNames=candidates.map(w=>w.name),matchBasis=order.workerAssignment?.workerId?'订单人工指定':part.workers.length?'工件指定人员':'按加工类别匹配',selection=candidates.length===1?'唯一可加工人员':'候选人中预计最早完成';for(const p of best.plan){const cap=useOvertime?best.w.overtime:best.w.capacity,k=best.w.id+'|'+p.date;loads.set(k,(loads.get(k)||0)+p.amount);out.push({orderId:order.id,drawingNo:order.drawingNo||part.drawingNo,date:p.date,worker:best.w.name,orderNo:order.orderNo,partCode:order.partCode,name:order.name,amount:p.amount,capacity:cap,due:order.due,status:p.date<=order.due?'按期':'延期',reason:`${matchBasis}；${selection}${useOvertime?'；加班产能待主管批准':''}`,candidates:candidateNames})}if(best.remaining>.001){const cap=Math.max(1,useOvertime?best.w.overtime:best.w.capacity);let estimated=best.plan.at(-1)?.date||workday(today());for(let i=0;i<Math.ceil(best.remaining/cap);i++)estimated=workday(addDay(estimated));shortages.push({orderId:order.id,drawingNo:order.drawingNo||part?.drawingNo,orderNo:order.orderNo,partCode:order.partCode,name:order.name,due:order.due,requiredWork,scheduledWork:requiredWork-best.remaining,remainingWork:best.remaining,remainingQty:best.remaining/part.unit,suggestedWorker:best.w.name,estimatedFinish:estimated,reason:'六工作日计划窗口内产能不足'})}
 }
 return {allocations:out.sort((a,b)=>a.date.localeCompare(b.date)||a.worker.localeCompare(b.worker)),shortages};
}

